        std::getline(std::cin, line);
        std::istringstream iss(line);
        std::vector<int> arr;
        int num;
        while (iss >> num) {
            arr.push_back(num);
        }

        std::string result = "YES";

        // Convert to 0-based index
        int first = arr[x - 1];
        if (first == 0) {
            result = "NO";
        } else {
            int second = arr[first - 1];
            if (second == 0) {
                result = "NO";
            }
        }

        std::cout << result << '\n';
    }

    return 0;
}

